/**
 * Challenge-bound Ed25519 signed native approval verification for Warden.
 *
 * Closes the loopback impersonation gap for native approvers (Mac app with
 * Keychain-bound key or paired iOS app with Face ID) by verifying an Ed25519
 * signature over a domain-separated canonical challenge binding:
 *   - approvalId
 *   - payload digest (HMAC-SHA256 of canonical tool input)
 *   - approved scope ("once" | "24h" | "always" | "task")
 *   - single-use cryptographic challenge nonce generated by the inbox
 *   - approval expiry timestamp (ms)
 *   - registered approver key id
 *
 * Registered public keys live in `<home>/warden/approvers.json` (mode 0600,
 * atomic write, quarantined if corrupt). Note: physical Keychain/Secure Enclave
 * key generation on macOS/iOS devices is a native-client concern; this module
 * implements the server-side verifier and key registry.
 */
import crypto from "node:crypto";
import path from "node:path";
import { newId, quarantineCorrupt, readJsonState, wardenDir, writeJsonAtomic } from "./store.js";
import type { GrantScope } from "./types.js";

const APPROVERS_VERSION = 1;
const CHALLENGE_DOMAIN = "lisa-warden-approval-v1";
const APPROVER_ID_RE = /^[a-zA-Z0-9_-]{3,80}$/;

export interface RegisteredApprover {
  id: string;
  label: string;
  publicKeyPem: string;
  createdAt: string;
  revokedAt?: string;
}

interface ApproversFile {
  version: typeof APPROVERS_VERSION;
  approvers: RegisteredApprover[];
}

export interface ApprovalChallenge {
  approvalId: string;
  digest: string;
  scope: GrantScope;
  nonce: string;
  expiresAt: number;
  approverId: string;
}

export interface ApprovalSignature {
  approverId: string;
  nonce: string;
  /** Base64- or base64url-encoded 64-byte Ed25519 signature over canonicalApprovalChallenge. */
  signature: string;
}

export type SignatureVerifyResult =
  | { ok: true; approverId: string }
  | {
      ok: false;
      error:
        | "signature_required"
        | "invalid_signature"
        | "unknown_approver"
        | "approver_revoked"
        | "nonce_mismatch"
        | "signature_replayed"
        | "expired";
      message: string;
    };

export function approversFile(home?: string): string {
  return path.join(wardenDir(home), "approvers.json");
}

/** Generate a fresh 32-byte hex challenge nonce for one pending approval. */
export function newChallengeNonce(): string {
  return crypto.randomBytes(32).toString("hex");
}

/** Canonical domain-separated bytes signed by a native approver key. */
export function canonicalApprovalChallenge(challenge: ApprovalChallenge): Buffer {
  const lines = [
    CHALLENGE_DOMAIN,
    `approvalId=${challenge.approvalId}`,
    `digest=${challenge.digest}`,
    `scope=${challenge.scope}`,
    `nonce=${challenge.nonce}`,
    `expiresAt=${Math.floor(challenge.expiresAt)}`,
    `approverId=${challenge.approverId}`,
  ];
  return Buffer.from(lines.join("\n"), "utf8");
}

/** Sign an approval challenge with an Ed25519 private key (PEM or KeyObject). */
export function signApprovalChallenge(
  challenge: ApprovalChallenge,
  privateKey: crypto.KeyLike,
): ApprovalSignature {
  const payload = canonicalApprovalChallenge(challenge);
  const sig = crypto.sign(null, payload, privateKey);
  return {
    approverId: challenge.approverId,
    nonce: challenge.nonce,
    signature: sig.toString("base64"),
  };
}

function isValidEd25519PublicPem(pem: string): boolean {
  try {
    const key = crypto.createPublicKey(pem);
    return key.asymmetricKeyType === "ed25519";
  } catch {
    return false;
  }
}

function parseApproversFile(value: unknown): ApproversFile | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const doc = value as Record<string, unknown>;
  if (doc.version !== APPROVERS_VERSION || !Array.isArray(doc.approvers)) return null;
  const approvers: RegisteredApprover[] = [];
  for (const raw of doc.approvers) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
    const r = raw as Record<string, unknown>;
    if (
      typeof r.id !== "string" ||
      !APPROVER_ID_RE.test(r.id) ||
      typeof r.label !== "string" ||
      typeof r.publicKeyPem !== "string" ||
      !isValidEd25519PublicPem(r.publicKeyPem) ||
      typeof r.createdAt !== "string"
    ) {
      return null;
    }
    if (r.revokedAt !== undefined && typeof r.revokedAt !== "string") return null;
    approvers.push({
      id: r.id,
      label: r.label,
      publicKeyPem: r.publicKeyPem,
      createdAt: r.createdAt,
      ...(r.revokedAt ? { revokedAt: r.revokedAt } : {}),
    });
  }
  return { version: APPROVERS_VERSION, approvers };
}

export async function loadApprovers(
  home?: string,
): Promise<{ approvers: RegisteredApprover[]; corrupt: boolean }> {
  const file = approversFile(home);
  const read = await readJsonState(file, parseApproversFile);
  if (read.state === "missing") return { approvers: [], corrupt: false };
  if (read.state === "corrupt") {
    await quarantineCorrupt(file, read.error);
    return { approvers: [], corrupt: true };
  }
  return { approvers: read.value.approvers, corrupt: false };
}

export async function registerApprover(
  input: { id?: string; label: string; publicKeyPem: string },
  home?: string,
  now: number = Date.now(),
): Promise<RegisteredApprover> {
  if (!isValidEd25519PublicPem(input.publicKeyPem)) {
    throw new Error("Approver publicKeyPem must be a valid Ed25519 public key in PEM format.");
  }
  const id = input.id ?? newId("apv");
  if (!APPROVER_ID_RE.test(id)) {
    throw new Error(`Invalid approver id: ${id}`);
  }
  const label = String(input.label || id)
    .trim()
    .slice(0, 120);
  const { approvers } = await loadApprovers(home);
  if (approvers.some((a) => a.id === id)) {
    throw new Error(`Approver already registered: ${id}`);
  }
  const record: RegisteredApprover = {
    id,
    label,
    publicKeyPem: input.publicKeyPem.trim(),
    createdAt: new Date(now).toISOString(),
  };
  await writeJsonAtomic(approversFile(home), {
    version: APPROVERS_VERSION,
    approvers: [...approvers, record],
  });
  return record;
}

export async function revokeApprover(
  id: string,
  home?: string,
  now: number = Date.now(),
): Promise<boolean> {
  const { approvers } = await loadApprovers(home);
  let changed = false;
  const next = approvers.map((a) => {
    if (a.id !== id || a.revokedAt) return a;
    changed = true;
    return { ...a, revokedAt: new Date(now).toISOString() };
  });
  if (!changed) return false;
  await writeJsonAtomic(approversFile(home), {
    version: APPROVERS_VERSION,
    approvers: next,
  });
  return true;
}

export function parseApprovalSignature(value: unknown): ApprovalSignature | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const v = value as Record<string, unknown>;
  if (
    typeof v.approverId !== "string" ||
    !APPROVER_ID_RE.test(v.approverId) ||
    typeof v.nonce !== "string" ||
    v.nonce.length < 16 ||
    v.nonce.length > 256 ||
    typeof v.signature !== "string" ||
    v.signature.length < 32 ||
    v.signature.length > 512
  ) {
    return null;
  }
  return {
    approverId: v.approverId,
    nonce: v.nonce,
    signature: v.signature,
  };
}

/**
 * Stateful verifier tracking consumed challenge nonces so a captured signature
 * cannot be replayed even if an item id or digest is resubmitted.
 */
export class SignedApprovalVerifier {
  private readonly consumedNonces = new Set<string>();
  private readonly maxTrackedNonces: number;

  constructor(opts: { maxTrackedNonces?: number } = {}) {
    this.maxTrackedNonces = opts.maxTrackedNonces ?? 10_000;
  }

  async verify(params: {
    home: string;
    approvalId: string;
    digest: string;
    scope: GrantScope;
    expectedNonce: string;
    expiresAt: number;
    signature: unknown;
    now?: number;
  }): Promise<SignatureVerifyResult> {
    const now = params.now ?? Date.now();
    if (now >= params.expiresAt) {
      return { ok: false, error: "expired", message: "The approval challenge has expired." };
    }
    const parsed = parseApprovalSignature(params.signature);
    if (!parsed) {
      return {
        ok: false,
        error: "invalid_signature",
        message: "Approval signature payload is missing required fields.",
      };
    }
    if (
      parsed.nonce.length !== params.expectedNonce.length ||
      !crypto.timingSafeEqual(Buffer.from(parsed.nonce), Buffer.from(params.expectedNonce))
    ) {
      return {
        ok: false,
        error: "nonce_mismatch",
        message: "Approval signature nonce does not match the pending challenge.",
      };
    }
    const replayKey = `${params.home}\u0000${parsed.nonce}`;
    if (this.consumedNonces.has(replayKey)) {
      return {
        ok: false,
        error: "signature_replayed",
        message: "This approval challenge nonce has already been used.",
      };
    }

    const { approvers, corrupt } = await loadApprovers(params.home);
    if (corrupt) {
      return {
        ok: false,
        error: "unknown_approver",
        message: "Registered approvers file was corrupt and could not be trusted.",
      };
    }
    const approver = approvers.find((a) => a.id === parsed.approverId);
    if (!approver) {
      return {
        ok: false,
        error: "unknown_approver",
        message: `Approver "${parsed.approverId}" is not registered.`,
      };
    }
    if (approver.revokedAt) {
      return {
        ok: false,
        error: "approver_revoked",
        message: `Approver "${parsed.approverId}" has been revoked.`,
      };
    }

    let sigBytes: Buffer;
    try {
      const normalized = parsed.signature.replace(/-/g, "+").replace(/_/g, "/");
      sigBytes = Buffer.from(normalized, "base64");
    } catch {
      return {
        ok: false,
        error: "invalid_signature",
        message: "Approval signature is not valid base64.",
      };
    }
    if (sigBytes.length !== 64) {
      return {
        ok: false,
        error: "invalid_signature",
        message: "Ed25519 signature must be 64 bytes.",
      };
    }

    const challengeBytes = canonicalApprovalChallenge({
      approvalId: params.approvalId,
      digest: params.digest,
      scope: params.scope,
      nonce: params.expectedNonce,
      expiresAt: params.expiresAt,
      approverId: parsed.approverId,
    });

    let valid: boolean;
    try {
      const pubKey = crypto.createPublicKey(approver.publicKeyPem);
      valid = crypto.verify(null, challengeBytes, pubKey, sigBytes);
    } catch {
      valid = false;
    }

    if (!valid) {
      return {
        ok: false,
        error: "invalid_signature",
        message: "Ed25519 signature verification failed.",
      };
    }

    // Consume nonce after cryptographic verification succeeds.
    if (this.consumedNonces.size >= this.maxTrackedNonces) {
      const oldest = this.consumedNonces.values().next().value;
      if (oldest !== undefined) this.consumedNonces.delete(oldest);
    }
    this.consumedNonces.add(replayKey);

    return { ok: true, approverId: parsed.approverId };
  }
}
